import sys
from typing import List

def is_beautiful(arr: List[int], k: int) -> bool:
    n = len(arr)
    if n % k != 0:
        return False
    target_sum = sum(arr[:k])
    for i in range(k, n):
        if sum(arr[i-k+1:i+1]) != target_sum:
            return False
    return True

