    if is_beautiful(arr, k):
        return arr
    if n % k != 0:
        return [-1]

    target_sum = sum(arr[:k])
    for i in range(n, 0, -1):
        if (i - n) % k == 0:
            new_arr = arr + [i] * ((i - n) // k)
            if is_beautiful(new_arr, k):
                return new_arr
    return [-1]

