from itertools import product

MOD = 10**9 + 7

def apply_filters(photo, filters):
    result = list(photo)
    for f in filters:
        for i in range(10):
            if f[i] == '+':
                result[i] = 'b' if result[i] == 'w' else 'w'
    return ''.join(result)

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    index = 0
    T = int(data[index])
    index += 1

    results = []
    for _ in range(T):
        S = data[index]
        index += 1
        N = int(data[index])
        index += 1
        filters = data[index:index + N]
        index += N

        # Count the number of black and white pixels in the initial photo
        black_count = S.count('b')
        white_count = S.count('w')

        # If the photo is already all black, there are 2^N possible subsets (including the empty set)
        if black_count == 10:
            results.append(pow(2, N, MOD))
        else:
            # If the photo is all white, there is only 1 possible subset (the empty set)
            if white_count == 10:
                results.append(1)
            else:
                # If the photo is a mix of black and white pixels, we need to check all possible subsets of filters
                possible_states = set()
                for combo in product([0, 1], repeat=N):
                    new_photo = apply_filters(S, [filters[i] for i in range(N) if combo[i]])
                    possible_states.add(new_photo)
                results.append(len(possible_states) % MOD)

    for result in results:
        print(result)

if __name__ == "__main__":
