from collections import defaultdict

def can_form_keyboard(s):
    n = len(s)
    if n == 1:
        return True, 'abcdefghijklmnopqrstuvwxyz'

    # Create a graph where each character points to the next character in the string
    graph = defaultdict(list)
    for i in range(n - 1):
        graph[s[i]].append(s[i + 1])

    # Check if the graph is a valid topological sort
    in_degree = {char: 0 for char in graph}
    for neighbors in graph.values():
        for neighbor in neighbors:
            in_degree[neighbor] += 1

    # Kahn's algorithm to find topological sort
    queue = [char for char in in_degree if in_degree[char] == 0]
    topo_order = []

    while queue:
        char = queue.pop(0)
        topo_order.append(char)
        for neighbor in graph[char]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    # If there is a cycle, return False
    if len(topo_order) != 26:
        return False, ''

    # Construct the keyboard layout
    keyboard = list('abcdefghijklmnopqrstuvwxyz')
    for i, char in enumerate(topo_order):
        keyboard[char - 'a'] = char

    return True, ''.join(keyboard)

