import math
from typing import List

def find_non_indulging_chairs(n: int) -> List[int]:
    chairs = list(range(1, 4 * n + 1))
    result = []
    for i in range(n):
        result.append(chairs.pop(0))
        result.append(chairs.pop(3 * n - 1))
    return result

def gcd(a: int, b: int) -> int:
    return math.gcd(a, b)

def is_indulging(chair1: int, chair2: int) -> bool:
    return gcd(chair1, chair2) == 1 or chair1 % chair2 == 0 or chair2 % chair1 == 0

def is_valid_seating(chairs: List[int]) -> bool:
    for i in range(len(chairs)):
        for j in range(i + 1, len(chairs)):
            if is_indulging(chairs[i], chairs[j]):
                return False
    return True

def solve():
    t = int(input())
    for _ in range(t):
        n = int(input())
        chairs = find_non_indulging_chairs(n)
        while not is_valid_seating(chairs):
            chairs = find_non_indulging_chairs(n)
        print(*chairs)

if __name__ == "__main__":
    solve()

