import heapq

def can_form_network(N, a, b):
    if a[0] != 0 or b[N-1] != 0:
        return "No"

    pq = [(a[1], 1, 2)]
    visited = {1}

    while pq:
        dist, u, v = heapq.heappop(pq)
        if v == N:
            break
        if v in visited:
            continue
        visited.add(v)
        if dist != a[v-1]:
            return "No"
        if v + 1 <= N and v + 1 not in visited:
            heapq.heappush(pq, (dist + b[v], v, v + 1))
        if v - 1 >= 1 and v - 1 not in visited:
            heapq.heappush(pq, (dist + a[v-2], v, v - 1))

    if v != N or len(visited) != N:
        return "No"

    pq = [(b[N-2], N-1, N-2)]
    visited = {N}

    while pq:
        dist, u, v = heapq.heappop(pq)
        if v == 1:
            break
        if v in visited:
            continue
        visited.add(v)
