def power(x, y):
    result = 1
    while y > 0:
        if y % 2 == 1:
            result = (result * x) % MOD
        y = y // 2
        x = (x * x) % MOD
    return result

def factorial_mod(n, mod):
    fact = [1] * (n + 1)
    for i in range(2, n + 1):
        fact[i] = (fact[i - 1] * i) % mod
    return fact

def mod_inverse(x, mod):
    return power(x, mod - 2)

def solve(N):
    fact = factorial_mod(N, MOD)
    inv_fact = [0] * (N + 1)
    inv_fact[N] = mod_inverse(fact[N], MOD)
    for i in range(N - 1, -1, -1):
        inv_fact[i] = (inv_fact[i + 1] * (i + 1)) % MOD
    result = 1
    for i in range(1, N + 1):
        result = (result * power(i, N - i + 1) * inv_fact[i]) % MOD
    return result

